import type { ReactNode } from "react";

export const errorStateVariantValues = ["inline", "page"] as const;

/** What to show when a page or a panel could not be shown: a failed load, or a 404, 403 or 500 screen, with what happened and how to go on. */
export interface ErrorStateSpecProps {
  /**
   * Say what happened, e.g. "We could not load your invoices".
   */
  title: string;
  /**
   * Why it happened and what the person can do.
   */
  description?: string;
  /**
   * An icon above the title. Decorative. Without an icon or a code a warning icon is shown.
   */
  icon?: ReactNode;
  /**
   * A status code such as 404, shown large above the title.
   */
  code?: string;
  /**
   * What to do next: a Retry button, a link back.
   */
  actions?: ReactNode;
  /**
   * inline for inside a card or table; page for a whole screen.
   * @default "inline"
   */
  variant?: "inline" | "page";
  /**
   * Heading level of the title, 1 to 6. Use 1 when the error is the whole page.
   * @default 2
   */
  headingLevel?: number;
  /**
   * Announce it to screen readers (role alert). Turn it on only when the error appears after the page has loaded.
   * @default false
   */
  announce?: boolean;
  /**
   * Extra class names for single parts, so you can restyle one part without editing the file. Keys: root, icon, code, title, description, actions.
   */
  classNames?: Partial<Record<"root" | "icon" | "code" | "title" | "description" | "actions", string>>;
}

export const errorStateDefaults = {
  variant: "inline",
  headingLevel: 2,
  announce: false,
} as const;

export const errorStateMeta = {
  "name": "ErrorState",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;
